package net.minecraft.world.item.crafting;import java.util.*;import net.minecraft.world.item.ItemStack;public class RecipeManager{public boolean enabled=true;public int checks;public List<Holder> custom=new ArrayList<>();public List<Holder> getAllRecipesFor(String type){return custom;}public Optional<Holder> getRecipeFor(String type,SingleRecipeInput input,Object world){return input.item().id.equals("minecraft:beef")?Optional.of(new Holder(new Recipe())):Optional.empty();}public Optional<Holder> getRecipeFor(String type,CraftingInput input,Object world){checks++;if(!enabled)return Optional.empty();for(Holder h:custom)if(h.value().matches(input))return Optional.of(h);long wheat=input.grid().stream().filter(s->s.id.equals("minecraft:wheat")).count();if(wheat==3)return Optional.of(new Holder(new Recipe()));return Optional.empty();}public record Holder(Recipe value){}public static class Recipe{public boolean matches(CraftingInput input){return false;}public ItemStack assemble(CraftingInput i,Object w){return new ItemStack("minecraft:bread",1);}public List<ItemStack> getRemainingItems(CraftingInput i){return List.of();}}}